function saveSvg(file_name) {
	let svgStr = `<svg width="${width}" height="${height}" xmlns="http://www.w3.org/2000/svg">\n`;

	for (let i = 0; i < LAYERS.length; i++) {		
		svgStr += `<g id="${LAYERS[i]}" stroke="${LAYERS[i]}" fill="none">\n`;
		for (const poly of GRPS[i]) {
			svgStr += poly.toSVG();
		}
		svgStr += `</g>\n`;
	}

	svgStr += `</svg>`;

	save(svgStr.split("\n"), file_name + '.svg.txt');
}

