const PALETTES = [
	["navy", "deeppink", "cyan"], // CPB
	["cyan", "magenta", "yellow"], // CMY
	["cyan", "magenta", "yellow", "black"], // CMYK
	["red", "green", "blue"], // RGB
]
const ROWS = 3, SW = 2, PEN_PAD = 2, AMPL = 16;
let LAYERS, S, MAR = 0, BG, seed;

// https://github.com/epibyte/p5-epi-colors
const { EpiColors } = EpiColorsPckg;
let epiColors;

// https://github.com/epibyte/p5-epi-shapesvg
const { Polygon } = EpiShapeSvg;
let GRPS = [];

function setup() {
	// createCanvas(S=max(windowWidth, windowHeight), S);
	createCanvas(1200, 800);
	describe("Layers of softspliny lines overlaying providing fluent moire grid");
	frameRate(30);
	pixelDensity(1);
	MAR = ~~(S/20);

	epiColors = new EpiColors();
	epiColors.palettes.push(...PALETTES);
	epiColors.getRandomPalette(true);

	strokeWeight(SW);
	noFill();

	BG = epiColors.BG;
	LAYERS = epiColors.palette;
	if (frameCount === 0) {
		BG = color(~~random(255), ~~random(255), ~~random(255));
		LAYERS = PALETTES[0];
	}
	BG = color(~~random(255), ~~random(255), ~~random(255));
	BG = color("white");

	// shuffle(LAYERS, true);
	seed = ~~random(7654321);
	noiseSeed(seed);
	loop();	
}

function draw() {
	background(BG);
	blendMode(BLEND);

	GRPS = []; for (const LAY of LAYERS) GRPS.push([]); // console.log(GRPS)

	const WDH = width - MAR - MAR;
	const HGT = height - MAR - MAR;
	const t = millis()/10000;

	const yrows = HGT / ROWS;
	for (let y = 0; y < HGT;) {

		for (let i = 0; i < LAYERS.length; i++) {
			const LAY = LAYERS[i];
			stroke(LAY);

			// row
			const yy = calcTransition(y / yrows)
			const dir = !change_dir ? 1 : fract(yy) < 0.5 ? 1 : -1;

			ptsArr = [];
			for (let x = MAR; x < WDH+MAR; x+= 10) {
				const ns = noise(x/(WDH/3)+t*dir, yy/2, i + t)-0.5;
				// vertex(x, y + ns * AMPL);
				ptsArr.push([x, y + ns * AMPL + MAR]);
			}

			y += PEN_PAD; // for every pen goto next line

			const newPoly = new Polygon(ptsArr);
			newPoly.drawShape();
			GRPS[i].push(newPoly);
		}

	}

	// end generation

	// // noLoop() removed for animation
}

