}

// calculates transition between rows, that it sticks more 
// to the current row and has fluent transition to next row
function calcTransition(v) {
	function easeInOutCirc(x) {
		return x < 0.5
	  ? (1 - Math.sqrt(1 - Math.pow(2 * x, 2))) / 2
	  : (Math.sqrt(1 - Math.pow(-2 * x + 2, 2)) + 1) / 2;
	}

	if (fluid_rows) {
		v += sin(v+frameCount/10); // changing value for each v for unregular grids
	} else {	
		v += 0.5; // transition is around x.5, see https://easings.net/#easeInOutCirc
	}

	const intVal = ~~v;
	const fractVal = fract(v);

	return intVal + easeInOutCirc(fractVal);
}

